import json, urllib.request

PRIYA = "511abd41-a4d9-4b0e-9ef1-e7ea8779c09a"

query = f"""
query {{
  teams(first: 20) {{
    nodes {{
      id name key
      memberships(first: 50) {{
        nodes {{
          owner
          user {{ id name }}
        }}
      }}
    }}
  }}
}}
"""

body = json.dumps({"query": query}).encode()
req = urllib.request.Request("https://api.linear.app/graphql", data=body, headers={"Content-Type": "application/json"})
try:
    with urllib.request.urlopen(req) as r:
        d = json.load(r)
    for t in d["data"]["teams"]["nodes"]:
        owners = [m["user"]["name"] for m in t["memberships"]["nodes"] if m.get("owner") and m.get("user", {}).get("id") == PRIYA]
        allm = [(m["user"]["name"], m.get("owner")) for m in t["memberships"]["nodes"]]
        print(t["key"], t["name"], "->", allm, "PRIYA_OWNS:", bool(owners))
except Exception as e:
    print("ERROR:", e)

